CREATE OR REPLACE FUNCTION public.app_accept_user_invitation(p_token text, p_full_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_email TEXT;
    v_invitation_id UUID;
    v_inv_email TEXT;
    v_inv_role TEXT;
    v_inv_university_id UUID;
    v_status TEXT;
    v_expires_at TIMESTAMPTZ;
    v_now TIMESTAMPTZ := NOW();
    v_meta JSONB;
    v_exists BOOLEAN;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT email, raw_user_meta_data
    INTO v_email, v_meta
    FROM auth.users
    WHERE id = v_user_id;

    IF v_email IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'user_not_found');
    END IF;

    SELECT id, email, role, university_id, status, expires_at
    INTO v_invitation_id, v_inv_email, v_inv_role, v_inv_university_id, v_status, v_expires_at
    FROM app.user_invitations
    WHERE token = p_token
    LIMIT 1;

    IF v_invitation_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invitation_not_found');
    END IF;

    IF LOWER(v_inv_email) <> LOWER(v_email) THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'email_mismatch');
    END IF;

    IF v_status <> 'pending' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invitation_not_pending');
    END IF;

    IF v_expires_at IS NOT NULL AND v_expires_at <= v_now THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invitation_expired');
    END IF;

    v_meta := COALESCE(v_meta, '{}'::JSONB);

    IF v_inv_role = 'university' THEN
        IF v_inv_university_id IS NULL THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invitation_missing_university');
        END IF;
        v_meta := v_meta
            || JSONB_BUILD_OBJECT('role', 'university')
            || JSONB_BUILD_OBJECT('university_id', v_inv_university_id::TEXT);
    ELSIF v_inv_role = 'instructor' THEN
        v_meta := v_meta || JSONB_BUILD_OBJECT('role', 'instructor');
    ELSIF v_inv_role = 'admin' THEN
        v_meta := v_meta || JSONB_BUILD_OBJECT('role', 'admin');
    ELSE
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'unsupported_role');
    END IF;

    IF p_full_name IS NOT NULL AND LENGTH(TRIM(p_full_name)) > 0 THEN
        v_meta := v_meta || JSONB_BUILD_OBJECT('full_name', TRIM(p_full_name));
    END IF;

    UPDATE auth.users
    SET raw_user_meta_data = v_meta
    WHERE id = v_user_id;

    IF v_inv_role = 'instructor' THEN
        SELECT EXISTS(SELECT 1 FROM app.instructors WHERE id = v_user_id)
        INTO v_exists;

        IF NOT v_exists THEN
            INSERT INTO app.instructors (id, full_name)
            VALUES (v_user_id, NULLIF(TRIM(p_full_name), ''));
        ELSE
            UPDATE app.instructors
            SET full_name = COALESCE(NULLIF(TRIM(p_full_name), ''), full_name),
                updated_at = NOW()
            WHERE id = v_user_id;
        END IF;
    END IF;

    UPDATE app.user_invitations
    SET status = 'used',
        used_at = v_now,
        updated_at = v_now
    WHERE id = v_invitation_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'role', v_inv_role
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_add_application_file(p_application_id uuid, p_file_type text, p_storage_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_student_id UUID;
    v_file_id UUID;
BEGIN
    SELECT student_id INTO v_student_id
    FROM app.applications
    WHERE id = p_application_id;

    IF v_student_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_not_found');
    END IF;

    IF v_student_id <> auth.uid() THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_owner');
    END IF;

    INSERT INTO app.application_files (application_id, file_type, storage_path)
    VALUES (p_application_id, p_file_type, p_storage_path)
    RETURNING id INTO v_file_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'file_id', v_file_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_add_application_message_from_admin_to_student(p_application_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_exists BOOLEAN;
    v_message_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF p_content IS NULL OR LENGTH(TRIM(p_content)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'empty_content');
    END IF;

    SELECT EXISTS(SELECT 1 FROM app.applications a WHERE a.id = p_application_id)
    INTO v_exists;

    IF NOT v_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_not_found');
    END IF;

    INSERT INTO app.application_messages (application_id, sender_role, audience, content)
    VALUES (p_application_id, 'admin', 'student', p_content)
    RETURNING id INTO v_message_id;

    UPDATE app.applications
    SET
        last_message_at = NOW(),
        updated_at = NOW()
    WHERE id = p_application_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'message_id', v_message_id
    );
END;
$function$

