CREATE OR REPLACE FUNCTION public.app_add_student_dossier_document(p_document_type text, p_storage_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_doc_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT(
            'success', FALSE,
            'error', 'not_authenticated'
        );
    END IF;

    IF p_document_type IS NULL OR LENGTH(TRIM(p_document_type)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT(
            'success', FALSE,
            'error', 'invalid_document_type'
        );
    END IF;

    IF p_storage_path IS NULL OR LENGTH(TRIM(p_storage_path)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT(
            'success', FALSE,
            'error', 'invalid_storage_path'
        );
    END IF;

    INSERT INTO app.student_dossier_documents (student_id, document_type, storage_path)
    VALUES (v_user_id, p_document_type, p_storage_path)
    RETURNING id INTO v_doc_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'document_id', v_doc_id
    );
END;
$function$
